       DB::transaction(function () use ($clients) {
           // تحويل JSON إلى مصفوفة
           $clientList = json_decode($clients[0]['all_clients_array'], true);

           if (!is_array($clientList)) {
               throw new \Exception('البيانات غير صالحة');
           }

           // تجهيز بيانات items
           $itemsData = [];
           foreach ($clientList as $client) {
               [$name, $phone] = $client;
               $itemsData[] = [
                   'name' => $name,
                   'type' => 'Customer',
                   'department_id' => 1,
                   'main_group_id' => 3,
                   'sub_group_id' => null,
                   'branch_id' => 1,
                   'created_at' => now(),
                   'updated_at' => now(),
               ];
           }

           // إدخال items دفعة واحدة
           Item::insert($itemsData);

           // جلب آخر IDs بعد الإدخال
           $lastIds = Item::orderBy('id', 'desc')
               ->take(count($itemsData))
               ->pluck('id')
               ->reverse()
               ->values();

           // تجهيز بيانات customers
           $customersData = [];
           foreach ($lastIds as $index => $itemId) {
               $phone = $clientList[$index][1] ?? null;
               $customersData[] = [
                   'item_id' => $itemId,
                   'phone' => $phone,
                   'employee_id' => null,
                   'branch_id' => 1,
                   'sales_rout_id' => null,
                   'created_at' => now(),
                   'updated_at' => now(),
               ];
           }

           // إدخال customers دفعة واحدة
           Customer::insert($customersData);
       });



   }
}
